SET XACT_ABORT ON;
BEGIN TRAN;
DECLARE @Added TABLE(ID int);
INSERT @Added EXEC dbo.Save_Employee_Feedback_Type @Actor=1,@ID=0,@TitleAr=N'EF V3 test type',@TitleEn=N'EF V3 test type',@Order=90,@Active=1;
DECLARE @Type int=(SELECT ID FROM @Added); DELETE @Added;
INSERT @Added EXEC dbo.Save_Employee_Feedback_Topic @Actor=1,@ID=0,@Type=@Type,@Brand=29,@TitleAr=N'EF V3 topic',@TitleEn=N'EF V3 topic',@Order=90,@Active=1;
DECLARE @Topic int=(SELECT ID FROM @Added); DELETE @Added;
INSERT dbo.UsersMembers(Type,FullName_Ar,Fullname_En,Employee_Number,Brand_ID,Branch_ID,Department_ID,Shif_ID,PhoneNumber,MobileNumber,Email,IsActive,IsDeleted)
VALUES(4,N'EF V3 applicant',N'EF V3 applicant',900001,29,25,1,1,N'test-phone',N'test-mobile',N'ef-v3@example.invalid',1,0);
DECLARE @Employee int=CONVERT(int,SCOPE_IDENTITY());
INSERT @Added EXEC dbo.Insert_Employee_Feedback_Request @Actor=@Employee,@Type=@Type,@Topic=@Topic,@Title=N'EF V3 request',@Details=N'Synthetic verification',@Disclose=1,@Target=3,@Files=N'<files/>';
DECLARE @ID int=(SELECT ID FROM @Added); DELETE @Added;
IF NOT EXISTS(SELECT 1 FROM dbo.Employee_Feedback_Requests WHERE ID=@ID AND SourceType=1 AND ApplicantName=N'EF V3 applicant' AND ApplicantEmployeeNumber=900001 AND ApplicantMobile=N'test-mobile' AND ApplicantPhone=N'test-phone' AND ApplicantEmail=N'ef-v3@example.invalid' AND Branch_ID=25 AND Brand_ID=29 AND ApplicantDataCapturedAt IS NOT NULL AND ApplicantDataIsBackfilled=0 AND Brand_Title_Ar IS NOT NULL AND Branch_Title_Ar IS NOT NULL) THROW 51500,'Account snapshot was not captured',1;
DECLARE @Contact TABLE(SourceType int,BrandName nvarchar(max),BranchName nvarchar(max),CapturedAt datetime,IsBackfilled bit,CanViewContact bit,ApplicantName nvarchar(max),ApplicantNameEn nvarchar(max),ApplicantEmployeeNumber int,ApplicantPhone nvarchar(max),ApplicantMobile nvarchar(max),ApplicantEmail nvarchar(max));
INSERT @Contact EXEC dbo.Select_Employee_Feedback_Contact @Actor=148,@ID=@ID;
IF NOT EXISTS(SELECT 1 FROM @Contact WHERE CanViewContact=1 AND ApplicantEmail=N'ef-v3@example.invalid') THROW 51500,'Disclosed contact unavailable',1;
UPDATE dbo.UsersMembers SET FullName_Ar=N'Changed account',MobileNumber=N'changed',PhoneNumber=N'changed',Email=N'changed@example.invalid',Branch_ID=(SELECT TOP(1) ID FROM dbo.Branches WHERE BrandID=29 AND ID<>25),Department_ID=NULL,Shif_ID=2 WHERE ID=@Employee;
DELETE @Contact;
INSERT @Contact EXEC dbo.Select_Employee_Feedback_Contact @Actor=148,@ID=@ID;
IF NOT EXISTS(SELECT 1 FROM @Contact WHERE ApplicantName=N'EF V3 applicant' AND ApplicantEmail=N'ef-v3@example.invalid' AND ApplicantMobile=N'test-mobile') THROW 51500,'Snapshot changed with profile',1;
IF NOT EXISTS(SELECT 1 FROM dbo.Employee_Feedback_RequestTargets(@ID,6,148) WHERE ID=160) THROW 51500,'Routing did not use stored department/branch',1;
DECLARE @V binary(8)=(SELECT RowVersion FROM dbo.Employee_Feedback_Requests WHERE ID=@ID);
EXEC dbo.Update_Employee_Feedback_Action @Actor=148,@ID=@ID,@Version=@V,@Action=2,@TargetType=2,@Comment=N'Snapshot routing',@Files=N'<files/>';
IF NOT EXISTS(SELECT 1 FROM dbo.Employee_Feedback_Workflow WHERE Request_ID=@ID AND ActionType=2 AND ReceiverID=147) THROW 51500,'Transfer did not use original branch',1;
UPDATE dbo.UsersMembers SET Branch_ID=25,Department_ID=1,Shif_ID=1 WHERE ID=@Employee;
INSERT @Added EXEC dbo.Insert_Employee_Feedback_Request @Actor=@Employee,@Type=@Type,@Topic=@Topic,@Title=N'EF V3 anonymous',@Details=N'Test',@Disclose=0,@Target=1,@Files=N'<files/>';
DECLARE @Anonymous int=(SELECT ID FROM @Added);
DELETE @Contact;
INSERT @Contact EXEC dbo.Select_Employee_Feedback_Contact @Actor=1,@ID=@Anonymous;
IF EXISTS(SELECT 1 FROM @Contact WHERE CanViewContact<>0 OR ApplicantName<>N'هوية غير معلنة' OR ApplicantNameEn IS NOT NULL OR ApplicantEmployeeNumber IS NOT NULL OR ApplicantPhone IS NOT NULL OR ApplicantMobile IS NOT NULL OR ApplicantEmail IS NOT NULL) THROW 51500,'Hidden contact leaked',1;
IF NOT EXISTS(SELECT 1 FROM @Contact WHERE BrandName IS NOT NULL AND BranchName IS NOT NULL) THROW 51500,'Public brand/branch absent',1;
DELETE @Contact;
INSERT @Contact EXEC dbo.Select_Employee_Feedback_Contact @Actor=@Employee,@ID=@Anonymous;
IF NOT EXISTS(SELECT 1 FROM @Contact WHERE CanViewContact=1) THROW 51500,'Owner cannot view own contact',1;
DECLARE @Stats TABLE(Dimension varchar(20),Value int,Label nvarchar(300),Total int);
INSERT @Stats EXEC dbo.Select_Employee_Feedback_Statistics @Actor=1,@Type=@Type,@Source=1;
IF NOT EXISTS(SELECT 1 FROM @Stats WHERE Dimension='type' AND Value=@Type AND Total=2 AND Label=N'EF V3 test type') THROW 51500,'Dynamic type statistics failed',1;
IF NOT EXISTS(SELECT 1 FROM @Stats WHERE Dimension='source' AND Value=1 AND Total=2) THROW 51500,'Employee source statistics failed',1;
-- Reserved customer discriminator; no public customer form is installed here.
UPDATE dbo.Employee_Feedback_Requests SET SourceType=2 WHERE ID=@ID;
DELETE @Stats; INSERT @Stats EXEC dbo.Select_Employee_Feedback_Statistics @Actor=1,@Type=@Type,@Source=2;
IF NOT EXISTS(SELECT 1 FROM @Stats WHERE Dimension='source' AND Value=2 AND Label=N'زبون' AND Total=1) THROW 51500,'Customer source statistics failed',1;
DECLARE @TypeVersion binary(8)=(SELECT RowVersion FROM dbo.Employee_Feedback_Types WHERE ID=@Type);
EXEC dbo.Save_Employee_Feedback_Type @Actor=1,@ID=@Type,@TitleAr=N'EF V3 renamed',@TitleEn=N'EF V3 renamed',@Order=90,@Active=0,@Version=@TypeVersion;
DECLARE @Types TABLE(ID int,Title_Ar nvarchar(200),Title_En nvarchar(200),Item_Order int,IsActive bit,IsDeleted bit,RowVersion binary(8));
INSERT @Types EXEC dbo.Select_Employee_Feedback_Types @Actor=151,@Mode=0;
IF EXISTS(SELECT 1 FROM @Types WHERE ID=@Type) THROW 51500,'Inactive type offered for submission',1;
ROLLBACK;
